package com.ivs.platform.audit.api;
import com.ivs.platform.audit.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/platform/audit-logs") public class AuditLogController{private final AuditLogService service;public AuditLogController(AuditLogService service){this.service=service;}@GetMapping @PreAuthorize("hasAuthority('USER_MANAGE')")public List<AuditLogEntry> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)String aggregateType,@RequestParam(required=false)UUID aggregateId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@RequestParam(defaultValue="200")int limit){return service.search(keyword,aggregateType,aggregateId,from,to,limit);}}
